const input = $('Prepare Send Payload').first().json;
const templates = $input.all().map(i => i.json);

// YCloud's "Get templates" returns every template on the account (no server-side filter),
// same as the disabled "Get templates" example node — filter here by name + language.
const matches = templates.filter(t => t.name === input.meta_template_name);
const template = matches.find(t => t.language === input.meta_language) || matches[0];

if (!template) {
  return [{ json: { __error: true, code: 404, message: `No WHATSAPP template found in YCloud for meta_template_name="${input.meta_template_name}" and meta_language="${input.meta_language}"` } }];
}

// NOTE: unverified — confirm the exact status field/enum YCloud returns for a template
// (assumed to mirror Meta's Cloud API: APPROVED / PENDING / REJECTED).
const status = template.status || template.meta_status;
if (status !== 'APPROVED') {
  return [{ json: { __error: true, code: 409, message: `Template "${input.meta_template_name}" is not approved yet (status: ${status || 'PENDING'})` } }];
}

if (!template.wabaId) {
  return [{ json: { __error: true, code: 500, message: `Template "${input.meta_template_name}" has no wabaId on the YCloud response` } }];
}

// Count {{n}} placeholders in the BODY component to validate the parameter count
// (replaces the old variables_schema column from communication_templates).
let expectedCount = null;
const bodyComponent = Array.isArray(template.components)
  ? template.components.find(c => String(c.type).toUpperCase() === 'BODY')
  : null;
if (bodyComponent && typeof bodyComponent.text === 'string') {
  const placeholders = bodyComponent.text.match(/\{\{\d+\}\}/g);
  expectedCount = placeholders ? new Set(placeholders).size : 0;
}

if (expectedCount !== null && input.parameters.length !== expectedCount) {
  return [{ json: { __error: true, code: 400, message: `Expected ${expectedCount} template parameters, received ${input.parameters.length}` } }];
}

const bodyFields = {};
input.parameters.forEach((p, i) => { bodyFields[`body_${i + 1}`] = p; });

return [{ json: {
  ...input,
  template_code: template.name,
  wabaId: template.wabaId,
  ...bodyFields,
} }];

const input = $('Validate Template & Params').first().json;
const res = $input.first().json;

// The custom YCloud node either returns the successful API response directly,
// or (via onError: continueErrorOutput) an error-shaped item. Exact field names
// are unverified — confirm with a live test send and adjust if needed.
const errorMessage = res.error?.message || (typeof res.error === 'string' ? res.error : null) || res.message;
const looksLikeSuccess = res.id != null || res.status != null || res.messages?.[0]?.id != null;

if (looksLikeSuccess && !errorMessage) {
  const messageId = res.id || res.messages?.[0]?.id || null;
  const status = res.status || res.messages?.[0]?.status || 'sent';
  const actionData = {
    phone: input.phone,
    meta_template_name: input.meta_template_name,
    template_code: input.template_code,
    parameters: input.parameters,
    message_id: messageId,
  };
  const esc = (value) => String(value).replace(/'/g, "''");
  return [{ json: {
    ...input,
    success: true,
    message_id: messageId,
    ycloud_status: status,
    action_data_sql: esc(JSON.stringify(actionData)),
  } }];
}

return [{ json: { __error: true, code: 502, message: `YCloud rejected the message: ${errorMessage || JSON.stringify(res)}` } }];

const input = $input.first().json;
const body = input.body ?? input;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const VALID_TEMPLATES = ['birthday', 'appointment_reminder', 'invoice_due'];

const patientId = String(body.id ?? '').trim();
if (!UUID_PATTERN.test(patientId)) throw new Error('id must be a valid patient UUID');

const templateCode = String(body.template_code ?? '').trim();
if (!VALID_TEMPLATES.includes(templateCode)) throw new Error(`Invalid template_code: ${body.template_code}`);

let appointmentId = '';
if (templateCode === 'appointment_reminder') {
  appointmentId = String(body.appointment_id ?? '').trim();
  if (!appointmentId) throw new Error('appointment_id is required for template_code=appointment_reminder');
}

return [{
  json: {
    patient_id: patientId,
    template_code: templateCode,
    appointment_id: appointmentId
  }
}];

