const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const reason = String(body.reason || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id is required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    reason: reason
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Cancel Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede cancelar` } }];
}

return [{ json: { ...input, from_status: status } }];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const desiredDate = String(body.desired_date || '').trim();
const desiredTime = String(body.desired_time || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId || !desiredDate || !desiredTime) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id, desired_date and desired_time are required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    desired_date: desiredDate,
    desired_time: desiredTime
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Update Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede reagendar` } }];
}

const durationMinutes = Math.round((new Date(appt.end_datetime).getTime() - new Date(appt.start_datetime).getTime()) / 60000) || 30;

return [{
  json: {
    ...input,
    from_status: status,
    original_assignee_id: appt.assignee_id,
    original_calendar_source_id: appt.calendar_source_id,
    duration_minutes: durationMinutes,
    summary: appt.summary,
    notes: appt.notes
  }
}];

const ctx = $('Validate Reschedule Eligibility1').first().json;
const calendarSourceIds = $input.first().json.calendar_source_ids || '';

const start = new Date(`${ctx.desired_date}T${ctx.desired_time}:00`);
const end = new Date(start.getTime() + ctx.duration_minutes * 60000);

return [{
  json: {
    startingDateAndTime: start.toISOString().replace('Z', ''),
    endingDateAndTime: end.toISOString().replace('Z', ''),
    durationInMinutes: ctx.duration_minutes,
    mode: 'checkAvailability',
    calendarSourceIds,
    appointmentId: ctx.appointment_id,
    doctorId: ctx.original_assignee_id || '',
    patientId: ctx.patient_id
  }
}];

const ctx = $('Build Availability Request (Reschedule)1').first().json;
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;

let chosen = null;
if (isAvailable) {
  const startIso = result.availableStartingTime;
  chosen = {
    assignee_id: result.availableDoctorId,
    assignee_name: result.availableDoctorName,
    calendar_source_id: result.availableCalendarSourceId,
    calendar_name: result.availableCalendarName,
    date: startIso ? startIso.slice(0, 10) : ctx.startingDateAndTime.slice(0, 10),
    time: startIso ? startIso.slice(11, 16) : ctx.startingDateAndTime.slice(11, 16)
  };
}

const suggestions = (result?.suggestedTimes || []).map((s) => ({
  assignee_id: s.user_id,
  assignee_name: s.user_name,
  calendar_source_id: s.calendar_source_id,
  calendar_name: s.calendar_name,
  date: s.fecha_cita,
  time: s.hora_cita
}));

return [{ json: { isAvailable, chosen, suggestions } }];

